const insertSnapshots = `-- name: InsertSnapshots :exec
INSERT INTO sales_intelligence.metric_snapshots (tenant_id, metric_key, period_grain, period_start, dimension, dimension_value, value, value_kind, currency, flags, computed_at)
SELECT $1::uuid, unnest($2::text[]), 'month', unnest($3::date[]), unnest($4::text[]), unnest($5::text[]),
  NULLIF(unnest($6::text[]), '')::numeric, unnest($7::text[]), NULLIF(unnest($8::text[]), ''), string_to_array(unnest($9::text[]), ','), $10::timestamptz
`

type InsertSnapshotsParams struct {
	TenantID   uuid.UUID
	Keys       []string
	Periods    []time.Time
	Dims       []string
	DimValues  []string
	Vals       []string
	Kinds      []string
	Currencies []string
	Flags      []string
	ComputedAt time.Time
}

// One statement for a whole rollup. COPY cannot be used: PostgreSQL refuses it under row-level
// security. An empty value means none; flags are comma-separated.
func (q *Queries) InsertSnapshots(ctx context.Context, arg InsertSnapshotsParams) error {
	_, err := q.db.Exec(ctx, insertSnapshots,
		arg.TenantID,
		arg.Keys,
		arg.Periods,
		arg.Dims,
		arg.DimValues,
		arg.Vals,
		arg.Kinds,
		arg.Currencies,
		arg.Flags,
		arg.ComputedAt,
	)
	return err
}

